void dei_rf_tx_irq( void )
{
    if( tmr_irq_int_sta( dei_rf.tx_tmr ) )
    {
        tmr_irq_dis( dei_rf.tx_tmr ) ;

        (dei_rf.tx_state)() ; 
    }
}

